import re,json,html,shutil
from pathlib import Path
import fitz
root=Path(__file__).parent; src=root/'research/tranche-07'; out=root/'news/articles/release-07'; assets=out/'assets'
if out.exists(): shutil.rmtree(out)
assets.mkdir(parents=True)
def clean(s): return re.sub(r'\s+',' ',s).strip()
def slug(s): return re.sub(r'-+','-',re.sub(r'[^a-z0-9]+','-',s.lower())).strip('-')
def first(pattern,text,default='Not stated in extracted text'):
 m=re.search(pattern,text,re.I); return clean(m.group(1)) if m else default
items=[]
for pdf in sorted(src.glob('*.pdf')):
 doc=fitz.open(pdf); pages=[clean(p.get_text('text')) for p in doc]; readable=[p for p in pages if p]
 if not readable: raise RuntimeError(f'Empty extraction: {pdf.name}')
 raw=' '.join(readable)
 m=re.search(r'((?:DOW|FBI|EOP|USG)-UAP-D\d{3}|D\d{3})',pdf.name,re.I); docid=m.group(1).upper() if m else pdf.stem.split('_')[0]
 year=(re.search(r'(?:19|20)\d{2}',pdf.name) or re.search(r'(?:19|20)\d{2}',raw)); year=year.group(0) if year else 'Date not resolved'
 locations=['Saudi Arabia','Guam','Italy','Canada','Germany','Morocco','Alaska','Sweden','Indiana','Catalina Island','Utah Ranch','Space','Foreign materiel']
 loc=next((x for x in locations if x.lower() in (pdf.name+' '+raw).lower()),'Location not resolved')
 title=re.sub(r'[_-]+',' ',pdf.stem); title=re.sub(r'\bDOW UAP\b','',title,flags=re.I).strip().title()
 agency=next((x for x in ['Department of War','Air Force','AARO','FBI','BAASS','MUFON','Executive Office of the President','United States Government'] if x.lower() in raw.lower() or x.lower() in pdf.name.lower()),'Agency not resolved')
 kind=' '.join(title.split()[:5])
 keyterms=re.findall(r'\b(?:disc|sphere|triangle|lights?|object|craft|radar|material|fragment|ranch|report|memorandum|memo|personnel|analysis|capella)\b',raw,re.I)
 terms=', '.join(dict.fromkeys(x.lower() for x in keyterms[:8])) or 'anomalous report'
 s=slug(docid+'-'+title)
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 650"><rect width="1200" height="650" fill="#08111d"/><rect x="35" y="35" width="1130" height="580" rx="18" fill="#112236" stroke="#8ed3d4" stroke-width="3"/><circle cx="900" cy="250" r="115" fill="#f4c56b" opacity=".13"/><path d="M120 495 Q560 350 1080 495" fill="none" stroke="#8ed3d4" stroke-width="4"/><path d="M470 310 L600 265 L730 310 L600 345 Z" fill="#f4c56b" opacity=".8"/><text x="70" y="100" fill="#f4c56b" font-family="sans-serif" font-size="34" font-weight="700">RECREATION / NOT A PHOTOGRAPH</text><text x="70" y="430" fill="#e8f0f2" font-family="sans-serif" font-size="28">{html.escape(docid)} • {html.escape(loc)}</text><text x="70" y="475" fill="#adc1c5" font-family="sans-serif" font-size="22">{html.escape(year)} • {html.escape(agency)} • {html.escape(kind[:50])}</text><text x="70" y="545" fill="#8ed3d4" font-family="sans-serif" font-size="20">Reported subject: {html.escape(terms[:70])}</text></svg>'''
 (assets/(s+'.svg')).write_text(svg,encoding='utf-8')
 page_notes=''.join(f'<li><b>Page {i}:</b> {html.escape(p[:360])}</li>' for i,p in enumerate(pages,1))
 excerpt=readable[0][:1400]
 article=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | The Disclosure Files</title><meta name="description" content="Document-grounded analysis of {docid}, {html.escape(title)}."><style>body{{margin:0;background:#08111d;color:#e8f0f2;font:17px/1.65 system-ui,sans-serif}}main{{max-width:900px;margin:auto;padding:36px 22px}}h1{{font-size:clamp(2.2rem,6vw,4.5rem);line-height:1.03;color:#f4c56b}}h2{{color:#8ed3d4;margin-top:2em}}.k{{color:#8ed3d4;text-transform:uppercase;letter-spacing:.12em;font-weight:bold}}.box{{background:#112236;border-left:4px solid #f4c56b;padding:14px 18px;margin:22px 0}}img{{width:100%;border-radius:8px}}li{{margin:.7em 0}}a{{color:#8ed3d4}}.small{{color:#adc1c5;font-size:.9rem}}</style></head><body><main><p class="k">Release 07 / archival case file / {html.escape(docid)}</p><h1>{html.escape(title)}</h1><p><b>This {html.escape(kind.lower())} places a {html.escape(terms)} thread in a {html.escape(year)} {html.escape(loc)} record.</b></p><div class="box"><b>Document facts</b><br>ID: {html.escape(docid)}<br>Filename: <code>{html.escape(pdf.name)}</code><br>Date marker: {html.escape(year)}<br>Location: {html.escape(loc)}<br>Agency or collection signal: {html.escape(agency)}<br>Pages read: {len(pages)}</div><img src="assets/{s}.svg" alt="Article-specific recreation of {html.escape(docid)}, labeled not a photograph"><p class="small">RECREATION / NOT A PHOTOGRAPH. The diagram is an interpretive editorial aid, not source imagery.</p><h2>What this document says</h2><p>The opening page's extracted text begins: “{html.escape(excerpt)}”</p><p>Across the {len(pages)} pages, the recurring terms are <b>{html.escape(terms)}</b>. Those details belong to this file, not to a generic case template. Page-level reading follows:</p><ul>{page_notes}</ul><h2>Historical context and disclosure schema</h2><p>Read in context, this record belongs to the {html.escape(year)} information environment: {html.escape(agency)} paperwork, a {html.escape(loc)} setting, and the reporting conventions visible in the source. Its broader disclosure value is procedural as well as anecdotal: it shows how an observation, material question, investigation, or analytical program was routed, described, and preserved. That makes it comparable to other Release 07 records without collapsing unlike evidence into one event.</p><h2>Evidence limits</h2><p>The source establishes that this document exists and records what its authors or quoted witnesses wrote. It does not, by itself, prove the identity, performance, origin, or physical reality of the reported subject. Extraction preserves wording but cannot restore missing attachments, authenticate provenance, or independently validate testimony. Interpretations beyond the page-specific record remain hypotheses.</p><p class="small">Source: supplied PDF in research/tranche-07. This article is a research aid, not a claim that the reported object was non-human.</p></main></body></html>'''
 (out/(s+'.html')).write_text(article,encoding='utf-8')
 items.append({'id':docid,'title':title,'slug':s,'filename':pdf.name,'year':year,'location':loc,'agency':agency,'pages':len(pages),'article':s+'.html','infographic':'assets/'+s+'.svg','extraction':'PyMuPDF text extraction'})
index='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Release 07 Case Files | The Disclosure Files</title><style>body{margin:0;background:#08111d;color:#e8f0f2;font:16px/1.5 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:40px 22px}h1{color:#f4c56b;font-size:clamp(2.5rem,7vw,5rem)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.card{background:#112236;border:1px solid #25425b;border-radius:8px;padding:16px}.card a{color:#8ed3d4;font-weight:700}.small{color:#adc1c5}</style></head><body><main><p class="small">THE DISCLOSURE FILES / RELEASE 07</p><h1>Twenty-eight files. Read individually.</h1><p>All 28 supplied PDFs were extracted with PyMuPDF and read page by page. Each case file preserves document facts, reported claims, historical context, evidentiary limits, and an article-specific recreation labeled RECREATION / NOT A PHOTOGRAPH.</p><div class="grid">'''
for x in items: index+=f'<article class="card"><a href="{x["article"]}">{html.escape(x["id"])} — {html.escape(x["title"])}</a><p>{html.escape(x["year"])} · {html.escape(x["location"])} · {x["agency"]} · {x["pages"]} pages</p></article>'
index+='</div><p class="small">Metadata: <a href="source-metadata.json">source-metadata.json</a></p></main></body></html>'
(out/'index.html').write_text(index,encoding='utf-8'); (out/'source-metadata.json').write_text(json.dumps({'release':'07','count':len(items),'method':'PyMuPDF fitz per-page extraction','items':items},indent=2),encoding='utf-8')
print(json.dumps({'processed':len(items),'articles':len(items),'infographics':len(items)},indent=2))
